"""Action-only referee for signed-helical martingale split/merge variance and share-scale no-go."""
import math
import numpy as np


def main():
    rng = np.random.default_rng(41082026)
    energy_res = helicity_res = mean_res = variance_res = entropy_violation = 0.0
    split_signal = merge_signal = 0.0

    for _ in range(30000):
        # Strict nondegenerate triangle generated by two nonparallel vectors.
        a = rng.normal(size=3)
        b = rng.normal(size=3)
        if np.linalg.norm(np.cross(a, b)) < 1e-4:
            continue
        k0 = a
        k1 = b
        k2 = -(a + b)
        r = np.array([np.linalg.norm(k0), np.linalg.norm(k1), np.linalg.norm(k2)])
        if np.min(r) < 1e-8:
            continue
        s = rng.choice([-1.0, 1.0], size=3)
        x = s * r
        R = float(rng.choice([-1.0, 1.0])) * float(rng.uniform(0.01, 5.0))
        T = np.array([
            (x[1] - x[2]) * R,
            (x[2] - x[0]) * R,
            (x[0] - x[1]) * R,
        ])
        P = np.maximum(T, 0.0)
        N = np.maximum(-T, 0.0)
        Q = float(P.sum())
        if Q < 1e-12:
            continue

        energy_res = max(energy_res, abs(float(T.sum())))
        helicity_res = max(helicity_res, abs(float(np.dot(x, T))))
        V2 = float(np.dot(x * x, T))
        donors = np.flatnonzero(N > 1e-12)
        recips = np.flatnonzero(P > 1e-12)

        if len(donors) == 1 and len(recips) == 2:
            d = int(donors[0])
            p = P[recips] / Q
            mean = float(np.dot(p, x[recips]))
            var = float(np.dot(p, (x[recips] - mean) ** 2))
            mean_res = max(mean_res, abs(mean - x[d]))
            variance_res = max(variance_res, abs(V2 - Q * var))
            split_signal = max(split_signal, Q * var)
            pp = float(p[0])
            h = -pp * math.log(pp) - (1.0 - pp) * math.log(1.0 - pp)
            entropy_violation = max(entropy_violation, max(0.0, 2.0 * pp * (1.0 - pp) - h))
        elif len(donors) == 2 and len(recips) == 1:
            rr = int(recips[0])
            q = N[donors] / Q
            mean = float(np.dot(q, x[donors]))
            var = float(np.dot(q, (x[donors] - mean) ** 2))
            mean_res = max(mean_res, abs(mean - x[rr]))
            variance_res = max(variance_res, abs(V2 + Q * var))
            merge_signal = max(merge_signal, Q * var)
        else:
            # Degenerate sign patterns may contain a numerically tiny root; ignore their classification.
            pass

    # Exact local share-scale counterexample: r=(1,16,16.5), all helicities +.
    L = 16.0
    delta = 0.5
    x = np.array([1.0, L, L + delta])
    T = np.array([x[1] - x[2], x[2] - x[0], x[0] - x[1]])
    P = np.maximum(T, 0.0)
    N = np.maximum(-T, 0.0)
    Q = float(P.sum())
    M = np.outer(N, P) / Q
    share = M[0, 1] / N[0]
    share_res = abs(share - 1.0)
    scale_product = share * L

    print(f"worst triad energy-conservation residual: {energy_res:.3e}")
    print(f"worst triad helicity-barycenter residual: {helicity_res:.3e}")
    print(f"worst conditional signed-frequency mean residual: {mean_res:.3e}")
    print(f"worst split/merge variance identity residual: {variance_res:.3e}")
    print(f"worst binary entropy lower-bound violation: {entropy_violation:.3e}")
    print(f"maximum sampled split-variance signal: {split_signal:.3e}")
    print(f"maximum sampled merge-variance signal: {merge_signal:.3e}")
    print(f"explicit share=1 residual: {share_res:.3e}")
    print(f"explicit local share-times-scale product: {scale_product:.6f}")

    assert energy_res < 2e-12
    assert helicity_res < 2e-10
    assert mean_res < 2e-10
    assert variance_res < 2e-8
    assert entropy_violation < 2e-12
    assert split_signal > 1e-4 and merge_signal > 1e-4
    assert share_res < 2e-12 and scale_product > 10.0
    print("PASS: signed-helical branch-variance / share-scale no-go calibrations")


if __name__ == "__main__":
    main()
